{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Offerings — {{BUSINESS_NAME}}</title>
  <style>
    :root{--accent:#6b8a5a;--muted:#6b7178;--bg:#fbfbfa;--card:#ffffff;--glass:rgba(255,255,255,0.6);--shadow:0 6px 20px rgba(27,31,35,0.08);--radius:12px}
    html,body{height:100%;margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:#0f1720;background:linear-gradient(180deg, #fbfdf9 0%, #f7faf6 100%)}
    /* page pattern using an embedded, unique SVG */
    .hero{position:relative;padding:48px 24px 36px;overflow:hidden}
    .hero:before{content:"";position:absolute;inset:0;background-image:url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="800" height="400" viewBox="0 0 800 400"><defs><linearGradient id="g1" x1="0" x2="1"><stop offset="0" stop-color="%236b8a5a" stop-opacity="0.06"/><stop offset="1" stop-color="%23a2c29a" stop-opacity="0.02"/></linearGradient></defs><g fill="none"><rect width="800" height="400" fill="%23fbfbfa"/><path d="M0 320c80-60 160 0 240-20s160-120 240-80 160 20 320-40v220H0z" fill="url(%23g1)" opacity="0.9"/></g></svg>');background-size:cover;mix-blend-mode:soft-light;opacity:0.95;pointer-events:none}
    .container{max-width:1100px;margin:0 auto;position:relative}
    nav{display:flex;justify-content:space-between;align-items:center;gap:16px}
    .brand{font-weight:700;color:var(--accent)}
    .navlinks{display:flex;gap:12px}
    .navlinks a{color:var(--muted);text-decoration:none;padding:8px 12px;border-radius:8px}
    .navlinks a:hover{background:rgba(107,138,90,0.08);color:var(--accent)}
    h1{margin:12px 0 8px;font-size:28px}
    p.lead{margin:0;color:var(--muted);max-width:66ch}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:20px;margin-top:22px}
    .cards{display:grid;gap:14px}
    .card{background:var(--card);padding:16px;border-radius:var(--radius);box-shadow:var(--shadow);border:1px solid rgba(16,22,18,0.03)}
    .card h3{margin:0 0 8px}
    .muted{color:var(--muted);font-size:14px}
    .pricing{display:flex;gap:10px;flex-wrap:wrap}
    .pill{background:linear-gradient(180deg,rgba(107,138,90,0.12),rgba(107,138,90,0.04));padding:8px 10px;border-radius:999px;color:var(--accent);font-weight:600}
    button.cta{background:var(--accent);color:white;border:0;padding:10px 16px;border-radius:10px;cursor:pointer}
    .timeline{display:flex;flex-direction:column;gap:10px}
    .phase{display:flex;align-items:flex-start;gap:12px}
    .phase .dot{width:44px;height:44px;border-radius:10px;background:#fff;border:1px solid rgba(16,22,18,0.06);display:flex;align-items:center;justify-content:center;font-weight:700;color:var(--accent)}
    .phase.active .dot{background:linear-gradient(180deg,var(--accent),#8aae7f);color:white}
    .phase .body{flex:1}
    .disclaimer{font-size:13px;color:#7b7f82;margin-top:10px}
    footer{margin-top:32px;padding:24px 0;color:var(--muted);font-size:13px}
    @media(max-width:880px){.grid{grid-template-columns:1fr;}.hero{padding:28px 18px}.navlinks{display:none}}
  </style>
</head>
<body>
  <header class="hero">
    <div class="container">
      <nav>
        <div class="brand">{{BUSINESS_NAME}}</div>
        <div class="navlinks">
          <a href="index.html">Home</a>
          <a href="services.html" aria-current="page">Offerings</a>
          <a href="approach.html">Method</a>
          <a href="conditions.html">Conditions</a>
          <a href="pricing.html">Investment</a>
          <a href="about.html">Story</a>
          <a href="book.html">Schedule</a>
          <a href="contact.html">Contact</a>
        </div>
      </nav>
      <h1>Practical programs that fit into real lives</h1>
      <p class="lead">Short, guided cycles that blend lifestyle, targeted therapies, and coaching. Choose the scope that suits your season—each offering is structured as a clear start, a learning phase, and a path forward.</p>
      <div class="grid">
        <div>
          <div class="cards">
            <div class="card">
              <div style="display:flex;justify-content:space-between;align-items:start;gap:10px">
                <div>
                  <h3>Reset Cycle — 6 weeks</h3>
                  <div class="muted">A focused short series for digestion, sleep, or energy recalibration.</div>
                </div>
                <div class="pill">Weekly check-ins</div>
              </div>
              <p class="muted" style="margin-top:10px">Includes intake, two targeted lab suggestions (optional), and a weekly actionable roadmap. Educational emphasis — no promises of cure.</p>
            </div>
            <div class="card">
              <h3>Threads Program — 12 weeks</h3>
              <div class="muted">A layered pathway combining lifestyle coaching, gentle physical practice, and nutritional support.</div>
              <p class="muted" style="margin-top:8px">Ideal when several systems feel out of sync. Measured steps, documented goals, and small habit milestones.</p>
            </div>
            <div class="card">
              <h3>Ongoing Guidance — monthly</h3>
              <div class="muted">A maintenance loop for people who benefit from regular refinements and accountability.</div>
              <p class="muted" style="margin-top:8px">Flexible, month-to-month support emphasizing education and sustainable adjustments.</p>
            </div>
          </div>
          <div class="card" style="margin-top:14px;">
            <h3>Pricing frame</h3>
            <div class="pricing" style="margin-top:8px">
              <div class="pill">Reset Cycle — starting at $420</div>
              <div class="pill">Threads Program — starting at $1,150</div>
              <div class="pill">Ongoing Guidance — monthly $225</div>
            </div>
            <p class="muted" style="margin-top:8px">Prices reflect program structure and practitioner time. Labs, supplements, or specialty services are billed separately and discussed before recommendation.</p>
          </div>
        </div>
        <aside>
          <div class="card">
            <h3>Roadmap planner</h3>
            <div class="muted">Tap phases to set your tentative timeline. Each phase is educational and supportive — not a promise of cure.</div>
            <div class="timeline" id="timeline">
              <div class="phase" data-phase="1">
                <div class="dot">1</div>
                <div class="body">
                  <strong>Phase 1 — Stabilize (2–6 weeks)</strong>
                  <div class="muted">Foundational tweaks: sleep timing, baseline labs, short habit sprints.</div>
                </div>
              </div>
              <div class="phase" data-phase="2">
                <div class="dot">2</div>
                <div class="body">
                  <strong>Phase 2 — Deepen (6–12 weeks)</strong>
                  <div class="muted">Targeted therapies, movement prescription, and individualized nutrition experiments.</div>
                </div>
              </div>
              <div class="phase" data-phase="3">
                <div class="dot">3</div>
                <div class="body">
                  <strong>Phase 3 — Integrate (ongoing)</strong>
                  <div class="muted">Embedding practices, relapse planning, and transition to maintenance.</div>
                </div>
              </div>
            </div>
            <div class="disclaimer">Disclaimer: These phases outline a general sequence. Individual pacing varies. This program is educational and supportive, not a guaranteed cure. Clinical decisions will be personalized and discussed during care planning.</div>
            <div style="margin-top:12px;display:flex;gap:8px;align-items:center">
              <button class="cta" id="planStart">Build a tentative plan</button>
              <a href="book.html" style="color:var(--accent);text-decoration:none;font-weight:600">Or schedule an inquiry</a>
            </div>
          </div>
          <div class="card" style="margin-top:12px">
            <h3>Ready to begin?</h3>
            <p class="muted">If you need a brief consult to decide which program fits, we offer a short orientation session.</p>
            <button class="cta" onclick="location.href='{{PRIMARY_CTA_URL}}'">{{PRIMARY_CTA_LABEL}}</button>
            <div style="margin-top:8px;color:var(--muted);font-size:13px">Call: {{PHONE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
          </div>
        </aside>
      </div>
      <footer>
        <div class="container">Serving {{CITY}}, {{STATE}} — Educational, integrative support. Not a substitute for emergency or urgent medical care.</div>
      </footer>
    </div>
  </header>
  <script>
    // timeline interactivity
    (function(){
      const timeline=document.getElementById('timeline');
      const phases=Array.from(timeline.querySelectorAll('.phase'));
      function setActive(n){
        phases.forEach(p=>p.classList.toggle('active', p.getAttribute('data-phase')===String(n)));
      }
      phases.forEach(p=>p.addEventListener('click',()=> setActive(p.getAttribute('data-phase'))));
      // default to phase 1
      setActive(1);
      document.getElementById('planStart').addEventListener('click',()=>{
        // lightweight planner: open booking with a query param describing desired phase
        const active=phases.find(p=>p.classList.contains('active')).getAttribute('data-phase');
        const url=new URL('{{PRIMARY_CTA_URL}}', location.href);
        url.searchParams.set('phase', active);
        location.href=url.toString();
      });
    })();
  </script>
</body>
</html>"} 
{"path":"conditions.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Conditions & Support — {{BUSINESS_NAME}}</title>
  <style>
    :root{--accent:#7a5a9b;--muted:#546069;--bg:#fffefc;--card:#fff;--radius:10px}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:var(--bg);color:#0c1112}
    header{padding:20px 18px;border-bottom:1px solid rgba(10,14,12,0.04)}
    .container{max-width:1000px;margin:0 auto;padding:18px}
    .brand{font-weight:700;color:var(--accent)}
    nav{display:flex;justify-content:space-between;align-items:center}
    nav a{color:var(--muted);text-decoration:none;padding:6px 10px;border-radius:6px}
    .hero{padding:18px 0}
    h1{margin:6px 0;font-size:24px}
    .lead{color:var(--muted);max-width:70ch}
    .columns{display:grid;grid-template-columns:1fr 320px;gap:20px;margin-top:18px}
    .card{background:var(--card);padding:14px;border-radius:var(--radius);box-shadow:0 6px 18px rgba(9,12,12,0.04)}
    .condition{margin-bottom:12px}
    .condition h3{margin:0 0 6px}
    .condition p{margin:0;color:var(--muted)}
    .support-btn{margin-top:8px;background:transparent;border:1px solid rgba(122,90,155,0.12);padding:8px 10px;border-radius:8px;color:var(--accent);cursor:pointer}
    .disclaimer{font-size:13px;color:#6b6f71;margin-top:12px}
    @media(max-width:900px){.columns{grid-template-columns:1fr}.navlinks{display:none}}
  </style>
</head>
<body>
  <header>
    <div class="container" style="display:flex;justify-content:space-between;align-items:center">
      <div class="brand">{{BUSINESS_NAME}}</div>
      <div class="navlinks">
        <a href="index.html">Home</a>
        <a href="services.html">Offerings</a>
        <a href="approach.html">Method</a>
        <a href="conditions.html" aria-current="page">Conditions</a>
        <a href="pricing.html">Investment</a>
        <a href="book.html">Schedule</a>
        <a href="contact.html">Contact</a>
      </div>
    </div>
  </header>
  <main class="container">
    <section class="hero">
      <h1>Conditions we commonly support</h1>
      <p class="lead">We provide evidence-informed, integrative education and structured support for a range of persistent issues. Below are common presentations and thoughtful next steps. Care is personalized; listed suggestions are starting points, not guarantees.</p>
      <div class="disclaimer card" style="margin-top:12px">Important: This information is educational and supportive. It is not a substitute for medical evaluation. If you are experiencing severe or worsening symptoms, please seek urgent care. Our approach does not promise cure; it aims to reduce burden, clarify options, and build sustainable practices.</div>
    </section>

    <div class="columns" style="margin-top:18px">
      <div>
        <div class="card">
          <div class="condition">
            <h3>Chronic sleep disturbance</h3>
            <p>Sleep issues often reflect a mix of circadian, behavioral, and physiologic contributors. We assess routines, stressors, and possible medical factors; propose a staged plan of sleep hygiene, timing adjustments, and gentle adjuncts.</p>
            <button class="support-btn" data-reco="Reset Cycle">Start with a short reset</button>
          </div>
          <div class="condition">
            <h3>Persistent digestive complaints</h3>
            <p>From bloating to irregularity, symptom mapping and selective testing help identify reversible contributors. Interventions emphasize nutrition, targeted eliminations, and gradual reintroduction experiments.</p>
            <button class="support-btn" data-reco="Threads Program">Consider a threads-length program</button>
          </div>
          <div class="condition">
            <h3>Low energy / fatigue</h3>
            <p>Fatigue is multi-factorial. We explore sleep, metabolic markers, movement, and stress-load. Small, measurable experiments replace sweeping promises.</p>
            <button class="support-btn" data-reco="Ongoing Guidance">Try a guided maintenance loop</button>
          </div>
          <div class="condition">
            <h3>Anxiety or overwhelm</h3>
            <p>We offer short, skills-focused cycles that teach breathwork, pacing, and behavioral adjustments alongside contextual supports. We coordinate with mental health specialists when appropriate.</p>
            <button class="support-btn" data-reco="Reset Cycle">A focused cycle can teach stabilizing tools</button>
          </div>
        </div>

        <div class="card" style="margin-top:12px">
          <h3>Extra resources</h3>
          <p class="muted">If you have a chronic condition not listed, we will still evaluate overlapping drivers and propose a personalized sequence of steps. We avoid unnecessary testing and prioritize educational value.</p>
        </div>
      </div>

      <aside>
        <div class="card">
          <h3>How we suggest starting</h3>
          <p class="muted">Short orientation, then choose either a focused cycle or a deeper program depending on complexity. We clarify expectations up front and adjust pacing to life demands.</p>
          <div style="margin-top:12px">
            <button class="cta" onclick="location.href='{{PRIMARY_CTA_URL}}'">{{PRIMARY_CTA_LABEL}}</button>
          </div>
        </div>

        <div class="card" style="margin-top:12px">
          <h3>Safety & scope</h3>
          <p class="muted">We do not provide emergency care. Complex medical diagnoses may require referral or co-management with specialists. All recommendations will emphasize transparency about the evidence and expected outcomes.</p>
        </div>

        <div class="card" style="margin-top:12px">
          <h3>Contact</h3>
          <p class="muted">Questions? <br/>Call: {{PHONE}}<br/><a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        </div>
      </aside>
    </div>

    <div class="disclaimer" style="margin-top:18px">Clinical disclaimer: The descriptions above are educational. They are not a guarantee of improvement or cure. Your care will be individualized; decisions about testing and interventions will be made together based on your history and preferences.</div>
  </main>
  <script>
    // Buttons map conditions to program suggestions and add a query to the booking link
    document.querySelectorAll('.support-btn').forEach(btn=>{
      btn.addEventListener('click',()=>{
        const recom=btn.getAttribute('data-reco');
        const url=new URL('{{PRIMARY_CTA_URL}}', location.href);
        url.searchParams.set('recommendation', recom);
        // small confirmation before redirect
        if(confirm('Open booking with suggested start: '+recom+'?')) location.href=url.toString();
      });
    });
  </script>
</body>
</html>"} 
{"path":"approach.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8"/>
  <meta name="viewport" content="width=device-width,initial-scale=1"/>
  <title>Method — {{BUSINESS_NAME}}</title>
  <style>
    :root{--accent:#c25a44;--muted:#5d6368;--card:#fff;--bg:#fffaf8}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Arial;background:var(--bg);color:#0b0f10}
    .wrap{max-width:1100px;margin:18px auto;padding:18px}
    header{display:flex;justify-content:space-between;align-items:center}
    .brand{font-weight:700;color:var(--accent)}
    nav a{margin-left:10px;color:var(--muted);text-decoration:none}
    .hero{display:flex;gap:18px;align-items:flex-start;margin-top:18px}
    .left{flex:1}
    .card{background:var(--card);padding:16px;border-radius:14px;box-shadow:0 8px 24px rgba(2,6,8,0.06)}
    .selector{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}
    .mood{padding:8px 12px;border-radius:10px;border:1px solid rgba(194,90,68,0.12);cursor:pointer}
    .mood.active{background:linear-gradient(180deg,var(--accent),#e07a62);color:white}
    .method-details{margin-top:14px}
    .method-details h2{margin:0 0 6px}
    .method-details p{margin:0;color:var(--muted)}
    .cta{margin-top:12px;background:var(--accent);color:white;padding:10px 14px;border-radius:10px;border:0;cursor:pointer}
    .roadmap{margin-top:16px;display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
    .roadmap .phase{padding:12px;border-radius:10px;background:linear-gradient(180deg,#fff,#fffaf5);border:1px solid rgba(10,14,12,0.04)}
    .roadmap strong{display:block;margin-bottom:6px}
    .note{font-size:13px;color:var(--muted);margin-top:10px}
    @media(max-width:880px){.hero{flex-direction:column}.roadmap{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div class="brand">{{BUSINESS_NAME}}</div>
      <nav>
        <a href="index.html">Home</a>
        <a href="services.html">Offerings</a>
        <a href="approach.html" aria-current="page">Method</a>
        <a href="conditions.html">Conditions</a>
        <a href="book.html">Schedule</a>
      </nav>
    </header>

    <section class="hero">
      <div class="left card">
        <h1 style="margin:0 0 6px">A practical match between mood and method</h1>
        <p class="note">Choose how you feel today — we’ll suggest an initial approach and tailor the entry point. This is an educational recommendation, not a diagnosis.</p>

        <div style="margin-top:12px">
          <div class="muted">I feel…</div>
          <div class="selector" id="moodSelector">
            <div class="mood" data-key="overloaded">Overloaded</div>
            <div class="mood" data-key="exhausted">Exhausted</div>
            <div class="mood" data-key="stuck">Stuck / plateaued</div>
            <div class="mood" data-key="curious">Curious / prevention</div>
          </div>

          <div class="method-details card" id="methodCard" style="margin-top:12px">
            <h2 id="methodTitle">Choose a mood above</h2>
            <p id="methodDesc">Select the phrase that fits best, and we’ll outline a modest first step and what to expect.</p>
            <ul id="methodList" style="margin-top:8px;color:var(--muted)"></ul>
            <div style="display:flex;gap:8px;align-items:center">
              <button class="cta" id="moodCta">{{PRIMARY_CTA_LABEL}}</button>
              <a id="moodHelp" href="contact.html" style="color:var(--accent);text-decoration:none">Ask a quick question</a>
            </div>
          </div>

        </div>

      </div>

      <aside style="width:340px">
        <div class="card">
          <h3>Method snapshot</h3>
          <p class="note">We layer small, evidence-minded actions: stabilize first, then targeted experiments, then integration. The goal is manageable learning rather than sweeping change.</p>
          <div class="roadmap" id="planner">
            <div class="phase">
              <strong>Phase 1</strong>
              <div class="muted">Stabilize & measure. Simple rules and baseline checks.</div>
            </div>
            <div class="phase">
              <strong>Phase 2</strong>
              <div class="muted">Targeted interventions and short trials.</div>
            </div>
            <div class="phase">
              <strong>Phase 3</strong>
              <div class="muted">Integration, relapse plans, and maintenance.</div>
            </div>
          </div>
          <div class="note">Planner note: Timeline estimates are flexible. We emphasize safety and collaborative decision-making. This is educational and not a medical guarantee.</div>
        </div>
      </aside>
    </section>

    <div style="margin-top:18px;text-align:center;color:var(--muted)">Serving {{CITY}}, {{STATE}} • For scheduling: {{PHONE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
  </div>

  <script>
    // Mood-to-Method mapping
    (function(){
      const mapping={
        overloaded:{title:'Short stabilizing loop',desc:'A brief, practical set of steps to reduce pressure and create breathing room.',items:["Daily micro-rests and pacing rules","Sleep window adjustments","One focused nutrition tweak"],cta:'Begin a stabilizing consult'},
        exhausted:{title:'Energy-focused reset',desc:'A structured exploration of sleep, rhythm, and low-burden movement to restore baseline energy.',items:["Sleep timing & daylight exposure","Gentle movement plan","Selective labs if indicated"],cta:'Start an energy reset'},
        stuck:{title:'Targeted experiment series',desc:'Design small, measurable trials to test what changes matter for you.',items:["Hypothesis-driven experiments","Progress review at 4–6 weeks","Adjust based on data"],cta:'Design my experiment series'},
        curious:{title:'Preventive pathway',desc:'A gentle, education-first series to shore up resilience and prevent drift.',items:["Foundational habits review","Quarterly check-ins","Tailored micro-habits"],cta:'Explore preventive options'}
      };

      const selector=document.getElementById('moodSelector');
      const moods=Array.from(selector.querySelectorAll('.mood'));
      const methodTitle=document.getElementById('methodTitle');
      const methodDesc=document.getElementById('methodDesc');
      const methodList=document.getElementById('methodList');
      const cta=document.getElementById('moodCta');

      function show(key){
        moods.forEach(m=>m.classList.toggle('active',m.getAttribute('data-key')===key));
        const v=mapping[key];
        methodTitle.textContent=v.title;
        methodDesc.textContent=v.desc;
        methodList.innerHTML='';
        v.items.forEach(it=>{const li=document.createElement('li');li.textContent=it;methodList.appendChild(li);});
        cta.textContent=v.cta;
        cta.onclick=()=>{
          const url=new URL('{{PRIMARY_CTA_URL}}', location.href);
          url.searchParams.set('mood', key);
          url.searchParams.set('entry', v.title);
          location.href=url.toString();
        };
      }

      moods.forEach(m=>m.addEventListener('click',()=> show(m.getAttribute('data-key'))));
      // preselect curious by default
      show('curious');
    })();
  </script>
</body>
</html>"} 
